#include <iostream>
#include <bit>

int main() {
    using namespace std;
    unsigned a, b;
    unsigned long C;
    cin >> a >> b >> C;
    unsigned c = popcount(C);

    if((a + b + c) % 2 != 0 || a + b + c > 120 || a > b + c || b > c + a || c > a + b){
        cout << "-1" << endl;
        return 0;
    }

    // n?? = X, Y の k 桁目が ?? であるような k の個数
    unsigned n00{60 - (a + b + c) / 2}, n01{(-a + b + c) / 2}, n10{(a - b + c) / 2}, n11{(a + b - c) / 2};

    unsigned long X{}, Y{};
    for(unsigned B = 60; B--;){ // 上の bit から見る
        // 1 bit ずつ上に持ち上げて
        X *= 2;
        Y *= 2;

        if(1 & (C >> B)){ // C の B bit 目が 1 なら
            if(n10){ // (1, 0) が余っていれば
                ++X; // X の B bit 目を 1, Y の b bit 目を 0 に
                --n10; // 在庫を減らす
            }else{ // 余っていなければ
                ++Y; // Y のほうを 1 に
                --n01; // 在庫を減らしておく
            }
        }else{ // B bit 目が 0 なら
            if(n00){ // (0, 0) が余っていれば
                --n00; // どちらも 0 にし、在庫を減らす
            }else{ // 余っていなければ
                ++X; // どちらも 1 にし、
                ++Y;
                --n11; // 在庫を減らす
            }
        }
    }

    cout << X << " " << Y << endl;
    return 0;
}
